{% endif %}

gcode_macro resume.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE'] | default({}) %}
{% set velocity = printer.configfile.settings.pause_resume.recover_velocity %}
{% set sp_move = client.speed_move | default(velocity) %}
{% set runout_resume = True if client.runout_sensor | default("") == ""
else True if not printer[client.runout_sensor].enabled
else printer[client.runout_sensor].filament_detected %}
{% set can_extrude = True if printer.toolhead.extruder == ''
else printer[printer.toolhead.extruder].can_extrude %}
{% set do_resume = False %}
{% set prompt_txt = [] %}


RESPOND TYPE=echo MSG="Resume: Restore: {last_extruder_temp.restore}, Temp: {last_extruder_temp.temp}/{last_extruder_temp.heater_bed_temp}, Status: {printer.idle_timeout.state | upper}"
{% if printer.idle_timeout.state | upper == "IDLE" or idle_state or force_restore %}
SET_GCODE_VARIABLE MACRO=RESUME VARIABLE=idle_state VALUE=False
{% if last_extruder_temp.restore %}

RESPOND TYPE=echo MSG='{"Restoring \"%s\" temperature to %3.1f/%3.1f\u00B0C Fan: %3.1f" % (printer.toolhead.extruder, last_extruder_temp.temp, last_extruder_temp.heater_bed_temp, last_extruder_temp.fan_speed) }'

_WAIT_TEMP EXTRUDER_TEMP={last_extruder_temp.temp} BED_TEMP={last_extruder_temp.heater_bed_temp} NAME=RESUME






SET_FAN_SPEED FAN=fanM106 SPEED={last_extruder_temp.fan_speed}
{% set do_resume = True %}
{% elif can_extrude %}
{% set do_resume = True %}
{% else %}
RESPOND TYPE=error MSG='{"Resumption interrupted !!! \"%s\" is not hot enough (1), please heat it up and press RESUME again" % printer.toolhead.extruder}'
{% set _d = prompt_txt.append("\"%s\" is not hot enough, please heat it up and press RESUME again" % printer.toolhead.extruder) %}
{% endif %}

{% elif can_extrude %}
{% set do_resume = True %}
{% else %}
RESPOND TYPE=error MSG='{"Resumption interrupted !!! \"%s\" is not hot enough (2), please heat it up and press RESUME again" % printer.toolhead.extruder}'
{% set _d = prompt_txt.append("\"%s\" is not hot enough, please heat it up and press RESUME again" % printer.toolhead.extruder) %}
{% endif %}
{% if runout_resume %}
{% if do_resume %}
{% if restore_idle_timeout > 0 %} SET_IDLE_TIMEOUT TIMEOUT={restore_idle_timeout} {% endif %}
{client.user_resume_macro | default("")}
_CLIENT_EXTRUDE
{% if last_extruder_temp.y > client.max_y %}
G1 Y{client.max_y} F{params.VELOCITY | default(sp_move)}
M400
G1 X{last_extruder_temp.x} F{params.VELOCITY | default(sp_move)}
M400
{% endif %}
RESUME_BASE VELOCITY={params.VELOCITY | default(sp_move)}
{% endif %}
{% else %}
RESPOND TYPE=error MSG='{"Resumption interrupted !!! \"%s\" has detected that the filament has run out, please load it and press RESUME" % (client.runout_sensor.split(" "))[1]}'
{% set _d = prompt_txt.append("\"%s\" has detected that the filament has run out, please load it and press RESUME" % (client.runout_sensor.split(" "))[1]) %}
{% endif %}

{% if not (runout_resume and do_resume) %}
RESPOND TYPE=command MSG="action:prompt_beginResumption interrupted!!!"
{% for element in prompt_txt %}
RESPOND TYPE=command MSG='{"action:prompt_text %s" % element}'
{% endfor %}
RESPOND TYPE=command MSG="action:prompt_footer_button Ok|RESPOND TYPE=command MSG=action:prompt_end|info"
RESPOND TYPE=command MSG="action:prompt_show"
{% endif %}



M400

